import re

_NUMBER_RE = re.compile(r"^-?\d+$")


class StackUnderflowError(Exception):
    pass


def _pop(stack, count):
    if len(stack) < count:
        raise StackUnderflowError("Insufficient number of items in stack")
    return [stack.pop() for _ in range(count)]


def _make_builtin(name):
    def builtin(stack):
        if name in ("+", "-", "*", "/"):
            b, a = _pop(stack, 2)
            if name == "+":
                stack.append(a + b)
            elif name == "-":
                stack.append(a - b)
            elif name == "*":
                stack.append(a * b)
            else:
                stack.append(a // b)
        elif name == "dup":
            if not stack:
                raise StackUnderflowError("Insufficient number of items in stack")
            stack.append(stack[-1])
        elif name == "drop":
            _pop(stack, 1)
        elif name == "swap":
            b, a = _pop(stack, 2)
            stack.append(b)
            stack.append(a)
        elif name == "over":
            if len(stack) < 2:
                raise StackUnderflowError("Insufficient number of items in stack")
            stack.append(stack[-2])

    return builtin


_BUILTINS = {
    name: _make_builtin(name)
    for name in ("+", "-", "*", "/", "dup", "drop", "swap", "over")
}


def evaluate(input_data):
    stack = []
    words = dict(_BUILTINS)

    def resolve(token):
        if _NUMBER_RE.match(token):
            value = int(token)
            return lambda s: s.append(value)
        name = token.lower()
        if name in words:
            return words[name]
        raise ValueError("undefined operation")

    for line in input_data:
        tokens = line.split()
        if not tokens:
            continue
        if tokens[0] == ":":
            name = tokens[1].lower()
            if _NUMBER_RE.match(tokens[1]):
                raise ValueError("illegal operation")
            body = [resolve(token) for token in tokens[2:-1]]
            words[name] = lambda s, body=body: [word(s) for word in body]
        else:
            for token in tokens:
                resolve(token)(stack)

    return stack

